function shell(){const u=state.user,staffSettings=!['pilgrim','agent'].includes(state.role)?`<div class="nav-label">System</div><button class="nav" data-page="settings">${icon('settings')}Settings & audit</button>`:'';return `<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('heart')}</div><div>HajjMed <span style="color:#e8c95e">Ghana</span></div></div><div class="nav-label">Workspace</div>${navItems().map(n=>`<button class="nav ${state.page===n[0]?'active':''}" data-page="${n[0]}">${icon(n[1])}${n[2]}</button>`).join('')}${staffSettings}<div class="side-bottom"><div class="sync"><i></i><span>Offline ready · Synced now</span></div><div class="user-mini"><div class="avatar">${u.initials}</div><div><strong style="font-size:11px">${u.name}</strong><small>${u.title}</small></div></div><button class="nav" id="logout">${icon('logout')}Sign out</button></div></aside><main class="main"><header class="topbar"><div style="display:flex;gap:10px;align-items:center"><button class="iconbtn menu-toggle" id="menu">${icon('menu')}</button><div class="top-title"><h1>Hajj 2027 Medical Operations</h1><p>Medical Directorate · Pilgrims Affairs Office Ghana</p></div></div><div class="top-actions"><span class="sync top-sync"><i></i>All changes synced</span><button class="iconbtn">${icon('bell')}</button>${['clinician','admin','medicaldirector'].includes(state.role)?`<button class="btn primary" id="newRecord">${icon('plus')} New record</button>`:''}</div></header><div id="content"></div></main><nav class="mobile-nav">${navItems().slice(0,4).map(n=>`<button class="${state.page===n[0]?'active':''}" data-page="${n[0]}">${icon(n[1])}${n[2].split(' ')[0]}</button>`).join('')}</nav></div>`}
function wire(){ $$('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()});$('#logout').onclick=()=>{state.user=null;login()};$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');const nr=$('#newRecord');if(nr)nr.onclick=()=>showEncounterChooser();enhanceBookingOptions();injectBackendShortcut();injectAuthorityHierarchy();injectVaccinationQR();injectSystemExamination();injectInvestigations();injectResultUpload();injectModuleActions();enforcePilgrimReadOnly();enforceAgentScope();enforceAgentAppointmentRegister();if(window.wireCommunications)wireCommunications() }
function injectBackendShortcut(){if(state.page!=='dashboard'||!['admin','medicaldirector'].includes(state.role))return;let hero=$('.hero');if(!hero||$('#openBackend'))return;let action=document.createElement('button');action.className='btn primary';action.id='openBackend';action.innerHTML=`${icon('settings')} Open backend`;action.onclick=()=>{state.page='backend';render()};hero.appendChild(action)}
function installUniqueRegistrationGuard(){let form=$('#passportForm'),phone=form?.querySelector('input[type="tel"]'),email=form?.querySelector('input[type="email"]');if(!form)return;phone.id='regPhone';email.id='regEmail';form.onsubmit=e=>{e.preventDefault();let passport=$('#regPassport').value.trim().toUpperCase(),phoneKey=phone.value.replace(/\D/g,''),emailKey=email.value.trim().toLowerCase();if(patients.some(p=>p.passport.toUpperCase()===passport)){toast('Duplicate blocked — this passport already has one pilgrim record');return}if(phoneKey&&registeredContacts.phones.has(phoneKey)){toast('Duplicate blocked — this phone number already belongs to a portal account');return}if(emailKey&&registeredContacts.emails.has(emailKey)){toast('Duplicate blocked — this email address already belongs to a portal account');return}registeredContacts.phones.add(phoneKey);if(emailKey)registeredContacts.emails.add(emailKey);toast('Unique passport identity verified — pilgrim account created');setTimeout(()=>form.closest('.modal').remove(),700)}}
function showClinicianRegistration(){let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<form class="modal-card clinician-registration" id="clinicianForm"><div class="modal-head"><div><span class="eyebrow" style="color:var(--green2)">Professional identity enrolment</span><h2>Register clinician account</h2><p class="sub">Access remains pending until professional registration and employment authority are verified.</p></div><button type="button" class="iconbtn" id="closeClinicianReg">×</button></div><div class="professional-warning">${icon('alert')}<div><strong>Professional accountability</strong><span>Clinical access does not transfer professional responsibility to the system. Each practitioner remains accountable for competent care, accurate documentation, omissions, negligence and decisions made under their professional licence.</span></div></div><div class="form-grid"><label class="field"><span>Full professional name *</span><input class="input" required></label><label class="field"><span>Profession *</span><select class="input" required><option value="">Select profession</option><option>Medical practitioner / Physician</option><option>Nurse or Midwife</option><option>Pharmacist</option><option>Allied health professional</option></select></label><label class="field"><span>Professional regulator *</span><select class="input" id="clinicianRegulator" required><option value="">Select regulator</option><option>Medical and Dental Council Ghana</option><option>Nursing and Midwifery Council of Ghana</option><option>Pharmacy Council Ghana</option><option>Allied Health Professions Council Ghana</option><option>Other recognised statutory regulator</option></select></label><label class="field"><span>Professional licence number *</span><input class="input" id="clinicianLicense" required minlength="4" maxlength="40" autocomplete="off" placeholder="Enter exactly as issued"></label><label class="field"><span>Registered email address *</span><input class="input" id="clinicianEmail" type="email" required></label><label class="field"><span>Registered mobile number *</span><input class="input" id="clinicianPhone" type="tel" required></label><label class="field"><span>Employing facility / Hajj team *</span><input class="input" required></label><label class="field"><span>Current licence expiry *</span><input class="input" id="clinicianExpiry" type="date" required></label></div><div class="licence-check"><b>Verification required before activation</b><span>The regulator, licence number, status, scope of practice and expiry will be checked against the regulator's authoritative register or through documented manual verification.</span></div><label class="check responsibility-check"><input type="checkbox" required>I declare that the information supplied is accurate, that my professional licence is current, and that I accept personal professional responsibility for care, documentation, negligence and practice outside my competence.</label><label class="check responsibility-check"><input type="checkbox" required>I agree to use the record only for authorised clinical duties and understand that all access, entries, amendments and overrides are audited.</label><div class="modal-actions"><span>Submission creates a pending account—not immediate clinical access.</span><button class="btn primary">Submit for licence verification</button></div></form>`;document.body.appendChild(modal);let close=()=>modal.remove();$('#closeClinicianReg').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};$('#clinicianForm').onsubmit=e=>{e.preventDefault();let licence=$('#clinicianLicense').value.trim().toUpperCase().replace(/\s+/g,''),email=$('#clinicianEmail').value.trim().toLowerCase(),phone=$('#clinicianPhone').value.replace(/\D/g,'');if(registeredProfessionalLicenses.has(licence)){toast('Duplicate blocked — this professional licence already has an account');return}if(registeredContacts.emails.has(email)||registeredContacts.phones.has(phone)){toast('Duplicate blocked — the email or phone already belongs to an account');return}if($('#clinicianExpiry').value<new Date().toISOString().slice(0,10)){toast('Registration blocked — professional licence is expired');return}registeredProfessionalLicenses.add(licence);registeredContacts.emails.add(email);registeredContacts.phones.add(phone);toast('Clinician registration submitted — licence verification pending');setTimeout(close,900)}}
function injectAuthorityHierarchy(){if(state.page!=='backend')return;let health=$('.backend-health');if(!health||$('.authority-hierarchy'))return;health.insertAdjacentHTML('afterend',`<div class="authority-hierarchy"><div><strong>Override authority hierarchy</strong><span>Medical Director › Administrator › Clinician / Agent / Pilgrim</span></div><div class="authority-rule"><b>Medical Director</b><span>Final override over every role, including administrators</span></div><div class="authority-rule"><b>Administrator</b><span>May override clinicians, agents and pilgrims; cannot override the Medical Director</span></div><button class="btn outline" id="testOverride">Test authority</button></div>`);$('#testOverride').onclick=()=>toast(state.role==='medicaldirector'&&canOverride('admin')?'Medical Director override authorised and audit event created':state.role==='admin'&&!canOverride('medicaldirector')?'Administrator cannot override the Medical Director':'Override evaluated under role hierarchy')}
function enhanceBookingOptions(){let service=$('#apptService');if(!service)return;if(!service.querySelector('[value="both"]'))service.insertAdjacentHTML('beforeend','<option value="both">Medical screening and vaccination</option><option value="review">Medical review · clinical decision only</option>');let region=$('#apptRegion')?.closest('.field');if(region&&!$('#apptVenue'))region.insertAdjacentHTML('afterend',`<label class="field"><span>Appointment venue</span><select class="input" id="apptVenue"><option>Hajj Village Accra</option><option>Hajj Village Tamale</option><option>Regional Medical Screening Centre</option><option>Designated Vaccination Centre</option></select></label>`)}
function enforcePilgrimReadOnly(){if(state.role!=='pilgrim'||state.page==='appointments')return;let content=$('#content');content.classList.add('pilgrim-readonly');content.querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true);['saveScreen','saveVaccines','addVax','encounter','saveConsent','newOrder','assignTask'].forEach(id=>{let e=$('#'+id);if(e)e.remove()});let hero=$('.pilgrim-hero');if(hero&&!$('.readonly-notice'))hero.insertAdjacentHTML('afterend',`<div class="readonly-notice">${icon('screen')}<span><strong>Verified health record · Read only</strong><small>Only appointment bookings can be changed by the pilgrim. Clinical and consent information is managed by authorised staff.</small></span></div>`)}
function enforceAgentAppointmentRegister(){if(state.role!=='agent'||state.page!=='appointments')return;let allowed=new Set(patients.filter(p=>p.agent===demoAgentName).map(p=>p.name));$$('tbody tr').forEach(row=>{let name=row.children[1]?.textContent;if(name&&!allowed.has(name))row.remove()})}
function enforceAgentScope(){if(state.role!=='agent')return;if(state.page==='appointments'){let select=$('#apptPilgrim');if(select){[...select.options].forEach(o=>{let p=patients.find(x=>x.id===o.value);if(p&&p.agent!==demoAgentName)o.remove()})}return}if(state.page!=='record')return;if(state.patient.agent!==demoAgentName){state.page='pilgrims';render();return}if(state.tab==='privacy'){state.tab='overview';render();return}let privacy=$('[data-tab="privacy"]');if(privacy)privacy.remove();let content=$('#content');content.classList.add('agent-readonly');content.querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true);['saveScreen','saveVaccines','addVax','encounter','saveConsent','newOrder','assignTask','saveInvestigations'].forEach(id=>{let e=$('#'+id);if(e)e.remove()});let top=$('.detail-top');if(top&&!$('.agent-scope-notice'))top.insertAdjacentHTML('afterend',`<div class="readonly-notice agent-scope-notice">${icon('screen')}<span><strong>Accredited-agent view · Read only</strong><small>Access is limited to approved information for pilgrims assigned to ${state.patient.agent}, including final screening outcomes and approved acute-care summaries. Detailed notes, consent logs and programme-wide operations remain restricted.</small></span></div>`)}
function injectSystemExamination(){if(state.tab!=='screening')return;let section=$$('.section-card').find(c=>c.textContent.includes('Physical examination & vital signs'));if(!section||section.querySelector('.systems-exam'))return;section.insertAdjacentHTML('beforeend',`<div class="systems-exam"><div class="systems-title"><div><h3>System examinations</h3><p>Record structured findings; abnormal results are added to the clinical-alert summary.</p></div><span class="badge green" id="examStatus"><i class="dot"></i>Within expected limits</span></div><div class="system-grid"><fieldset class="system-box"><legend><span>CV</span> Cardiovascular</legend><label>Pulse rhythm<select class="mini-input exam-param" data-alert="Irregular cardiac rhythm"><option value="normal">Regular</option><option value="abnormal">Irregular</option></select></label><label>Heart sounds<select class="mini-input exam-param" data-alert="Abnormal heart sounds"><option value="normal">S1/S2 normal</option><option value="abnormal">Added sounds</option></select></label><label>Murmur<select class="mini-input exam-param" data-alert="Cardiac murmur detected"><option value="normal">Absent</option><option value="abnormal">Present</option></select></label><label>JVP<select class="mini-input exam-param" data-alert="Elevated JVP"><option value="normal">Not elevated</option><option value="abnormal">Elevated</option></select></label><label>Peripheral oedema<select class="mini-input exam-param" data-alert="Peripheral oedema present"><option value="normal">None</option><option value="abnormal">Present</option></select></label><label>NYHA functional class<select class="mini-input exam-param" data-alert="NYHA functional limitation"><option value="normal">I — no limitation</option><option value="abnormal">II — slight limitation</option><option value="abnormal">III — marked limitation</option><option value="abnormal">IV — symptoms at rest</option></select></label></fieldset><fieldset class="system-box"><legend><span>RS</span> Respiratory</legend><label>Respiratory rate<input class="mini-input exam-number" id="examRR" type="number" min="5" max="50" value="16"><small>Expected adult resting range: 12–20/min</small></label><label>Work of breathing<select class="mini-input exam-param" data-alert="Increased work of breathing"><option value="normal">Normal</option><option value="abnormal">Increased / accessory muscles</option></select></label><label>Chest expansion<select class="mini-input exam-param" data-alert="Asymmetrical chest expansion"><option value="normal">Symmetrical</option><option value="abnormal">Asymmetrical</option></select></label><label>Auscultation<select class="mini-input exam-param" data-alert="Abnormal breath sounds"><option value="normal">Vesicular; no added sounds</option><option value="abnormal">Wheeze</option><option value="abnormal">Crackles</option><option value="abnormal">Reduced air entry</option></select></label><label>mMRC breathlessness grade<select class="mini-input exam-param" data-alert="mMRC breathlessness grade ≥1"><option value="normal">0 — only strenuous exercise</option><option value="abnormal">1 — hurrying / slight hill</option><option value="abnormal">2 — slower than peers</option><option value="abnormal">3 — stops after ~100 m</option><option value="abnormal">4 — too breathless to leave home</option></select></label></fieldset><fieldset class="system-box"><legend><span>GI</span> Abdominal</legend><label>Contour / distension<select class="mini-input exam-param" data-alert="Abdominal distension"><option value="normal">Not distended</option><option value="abnormal">Distended</option></select></label><label>Palpation<select class="mini-input exam-param" data-alert="Abdominal tenderness"><option value="normal">Soft, non-tender</option><option value="abnormal">Tenderness present</option><option value="abnormal">Guarding / rigidity</option></select></label><label>Organomegaly<select class="mini-input exam-param" data-alert="Hepatosplenomegaly"><option value="normal">None</option><option value="abnormal">Hepatomegaly</option><option value="abnormal">Splenomegaly</option><option value="abnormal">Both</option></select></label><label>Ascites<select class="mini-input exam-param" data-alert="Clinical ascites"><option value="normal">Not detected</option><option value="abnormal">Present</option></select></label><label>Bowel sounds<select class="mini-input exam-param" data-alert="Abnormal bowel sounds"><option value="normal">Normal</option><option value="abnormal">Reduced / absent</option><option value="abnormal">Hyperactive</option></select></label></fieldset><fieldset class="system-box"><legend><span>CNS</span> Neurological</legend><label>Orientation<select class="mini-input exam-param" data-alert="Disorientation detected"><option value="normal">Person, place and time</option><option value="abnormal">Impaired</option></select></label><div class="gcs-group"><small>Glasgow Coma Scale components</small><select class="mini-input gcs" id="gcsE"><option value="4">E4 spontaneous</option><option value="3">E3 to sound</option><option value="2">E2 to pressure</option><option value="1">E1 none</option></select><select class="mini-input gcs" id="gcsV"><option value="5">V5 orientated</option><option value="4">V4 confused</option><option value="3">V3 words</option><option value="2">V2 sounds</option><option value="1">V1 none</option></select><select class="mini-input gcs" id="gcsM"><option value="6">M6 obeys commands</option><option value="5">M5 localises</option><option value="4">M4 normal flexion</option><option value="3">M3 abnormal flexion</option><option value="2">M2 extension</option><option value="1">M1 none</option></select><b id="gcsTotal">GCS 15/15</b></div><label>Pupils<select class="mini-input exam-param" data-alert="Abnormal pupillary response"><option value="normal">Equal and reactive</option><option value="abnormal">Unequal / poorly reactive</option></select></label><label>Limb power<select class="mini-input exam-param" data-alert="Reduced limb power"><option value="normal">5/5 all limbs</option><option value="abnormal">Reduced / asymmetrical</option></select></label><label>Coordination / gait<select class="mini-input exam-param" data-alert="Abnormal coordination or gait"><option value="normal">Normal</option><option value="abnormal">Impaired / unsteady</option></select></label></fieldset></div><div class="exam-summary"><strong>Examination-generated findings</strong><span id="examFindings">No additional abnormal system findings.</span></div></div>`);$$('.exam-param',section).forEach(e=>e.onchange=updateExamSummary);$('#examRR').oninput=updateExamSummary;$$('.gcs',section).forEach(e=>e.onchange=updateExamSummary);updateExamSummary()}
function updateExamSummary(){let alerts=$$('.exam-param').filter(e=>e.value==='abnormal').map(e=>e.dataset.alert),rr=Number($('#examRR')?.value||0),gcs=['gcsE','gcsV','gcsM'].reduce((n,id)=>n+Number($('#'+id)?.value||0),0);if(rr&&((rr<12)||(rr>20)))alerts.push(`Respiratory rate outside expected range: ${rr}/min`);if(gcs<15)alerts.push(`Reduced Glasgow Coma Scale: ${gcs}/15`);if($('#gcsTotal'))$('#gcsTotal').textContent=`GCS ${gcs}/15`;let finding=$('#examFindings'),status=$('#examStatus');if(!finding||!status)return;finding.textContent=alerts.length?alerts.join(' · '):'No additional abnormal system findings.';status.className=`badge ${alerts.length?'red':'green'}`;status.innerHTML=`<i class="dot"></i>${alerts.length?alerts.length+' abnormal finding'+(alerts.length>1?'s':''):'Within expected limits'}`}
function injectInvestigations(){if(state.tab!=='results'||$('.investigations-suite'))return;let host=$('#tabBody');if(!host)return;const panel=(title,code,rows,status='Complete')=>`<div class="investigation-card"><div class="investigation-head"><div><span>${code}</span><h3>${title}</h3></div>${statusBadge(status)}</div><div class="lab-rows">${rows.map(r=>`<div class="lab-row"><div><strong>${r[0]}</strong><small>${r[3]||''}</small></div><input class="mini-input" value="${r[1]}" placeholder="Result"><span>${r[2]}</span><i class="${r[4]==='high'?'lab-high':r[4]==='low'?'lab-low':'lab-normal'}">${r[4]==='high'?'↑':r[4]==='low'?'↓':'✓'}</i></div>`).join('')}</div></div>`;host.insertAdjacentHTML('beforeend',`<section class="investigations-suite"><div class="investigation-title"><div><h2>Laboratory & diagnostic investigations</h2><p>Structured screening results and clinically indicated cardiovascular or imaging studies.</p></div><button class="btn primary investigation-action" data-test="Investigation order set">+ Order investigations</button></div><div class="investigation-policy"><b>Clinical-use policy</b><span>Results use the performing laboratory’s age-, sex- and method-specific reference intervals. Hormonal studies, chest X-ray, ECG and echocardiography require a documented indication; they are not universal screening tests.</span></div><div class="investigation-grid">${panel('Full Blood Count','FBC',[['Haemoglobin','12.7 g/dL','12.0–15.5','LOINC 718-7'],['White cell count','6.8 ×10⁹/L','4.0–11.0','LOINC 6690-2'],['Platelets','248 ×10⁹/L','150–400','LOINC 777-3'],['MCV','87 fL','80–100','LOINC 787-2']])}${panel('Renal Function & Electrolytes','RFT / U&E',[['Creatinine','88 µmol/L','Lab interval','LOINC 2160-0'],['eGFR','72 mL/min/1.73m²','≥60','CKD-EPI reported'],['Urea','5.4 mmol/L','2.5–7.8'],['Sodium','139 mmol/L','135–145'],['Potassium','4.2 mmol/L','3.5–5.1']])}${panel('Liver Function Tests','LFT',[['ALT','24 U/L','Lab interval'],['AST','22 U/L','Lab interval'],['ALP','91 U/L','Lab interval'],['Total bilirubin','11 µmol/L','Lab interval'],['Albumin','42 g/L','35–50']])}${panel('Hormonal Profile','ENDOCRINE',[['TSH','—','Lab interval','Order when clinically indicated'],['Free T4','—','Lab interval'],['Other hormone','—','Specify test and indication']],'Not ordered')}</div><div class="diagnostic-grid"><div class="diagnostic-card"><div class="diagnostic-head"><span>CXR</span><div><h3>Chest X-ray</h3><small>PA view unless alternative documented</small></div>${statusBadge('Not ordered')}</div><label>Clinical indication<textarea class="input" rows="2" placeholder="e.g. persistent respiratory symptoms, suspected TB or cardiac disease"></textarea></label><label>Radiology report<textarea class="input" rows="3" placeholder="Structured radiologist report"></textarea></label><button class="btn outline investigation-action" data-test="Chest X-ray">Order CXR</button></div><div class="diagnostic-card"><div class="diagnostic-head"><span>ECG</span><div><h3>12-lead ECG</h3><small>Rate, rhythm, conduction and QTc</small></div>${statusBadge('Ordered')}</div><div class="diagnostic-values"><label>Rate<input class="mini-input" value="78 bpm"></label><label>Rhythm<select class="mini-input"><option>Sinus rhythm</option><option>Atrial fibrillation</option><option>Other</option></select></label><label>PR<input class="mini-input" value="168 ms"></label><label>QRS<input class="mini-input" value="92 ms"></label><label>QTc<input class="mini-input" value="432 ms"></label><label>Interpretation<select class="mini-input"><option>Normal ECG</option><option>Abnormal — review</option></select></label></div><textarea class="input" rows="2" placeholder="Clinician interpretation and comparison"></textarea></div><div class="diagnostic-card"><div class="diagnostic-head"><span>ECHO</span><div><h3>Echocardiogram</h3><small>Transthoracic echo · clinically indicated</small></div>${statusBadge('Not ordered')}</div><div class="diagnostic-values"><label>LVEF<input class="mini-input" placeholder="%"></label><label>LV size<select class="mini-input"><option>Normal</option><option>Dilated</option></select></label><label>RV function<select class="mini-input"><option>Normal</option><option>Reduced</option></select></label><label>Valves<select class="mini-input"><option>No significant lesion</option><option>Abnormal</option></select></label><label>PASP<input class="mini-input" placeholder="mmHg"></label><label>Pericardium<select class="mini-input"><option>No effusion</option><option>Effusion present</option></select></label></div><textarea class="input" rows="2" placeholder="Cardiology conclusion"></textarea><button class="btn outline investigation-action" data-test="Echocardiogram">Order echocardiogram</button></div></div><div class="investigation-footer"><span>Critical or abnormal verified results create a clinician task and longitudinal clinical alert.</span><button class="btn primary" id="saveInvestigations">Save investigation results</button></div></section>`);$$('.investigation-action').forEach(b=>b.onclick=()=>toast(`${b.dataset.test} opened with indication required`));$('#saveInvestigations').onclick=()=>toast('Investigation results saved — abnormal findings sent to clinical history')}
function injectResultUpload(){if(state.tab!=='results'||$('.result-upload-centre'))return;let host=$('#tabBody');if(!host)return;let existing=[{name:'FBC_29Aug2026.pdf',type:'Full Blood Count',date:'29 Aug 2026',facility:'Hajj Village Accra Laboratory',size:'284 KB',status:'Verified'},{name:'ECG_12lead_29Aug.png',type:'12-lead ECG',date:'29 Aug 2026',facility:'Hajj Village Accra Diagnostics',size:'1.8 MB',status:'Reviewed'}].concat(state.uploads.filter(x=>x.patientId===state.patient.id));host.insertAdjacentHTML('beforeend',`<section class="result-upload-centre"><div class="investigation-title"><div><h2>External results & imaging uploads</h2><p>Attach reports supplied by an accredited laboratory, imaging centre or specialist.</p></div></div><div class="upload-layout"><form class="section-card" id="resultUploadForm"><div class="section-heading"><b>↑</b><div><h3>Upload investigation result</h3><p>Files remain linked to this pilgrim and the original order</p></div></div><div class="form-grid"><label class="field"><span>Investigation *</span><select class="input" id="uploadCategory" required><option value="">Select investigation</option><optgroup label="Laboratory"><option>Full Blood Count (FBC)</option><option>Renal Function / U&E (RFT)</option><option>Liver Function Tests (LFT)</option><option>Hormonal Profile</option><option>Other Laboratory Test</option></optgroup><optgroup label="Imaging & Cardiac"><option>Chest X-ray (CXR)</option><option>12-lead ECG</option><option>Echocardiogram</option><option>Other Imaging</option></optgroup></select></label><label class="field"><span>Collection / study date *</span><input class="input" id="uploadDate" type="date" value="2026-08-30" required></label><label class="field span2"><span>Laboratory / imaging facility *</span><input class="input" id="uploadFacility" required placeholder="Facility and location"></label><label class="field span2"><span>Clinical interpretation</span><textarea class="input" id="uploadNotes" rows="2" placeholder="Summary, abnormal findings or follow-up action"></textarea></label></div><label class="result-drop" for="resultFiles"><div>${icon('file')}</div><strong>Select laboratory or imaging files</strong><span>PDF, JPEG, PNG, WebP or DICOM · Multiple files accepted · Maximum 25 MB each</span><b>Browse files</b><input type="file" id="resultFiles" multiple required accept="application/pdf,image/jpeg,image/png,image/webp,.dcm,application/dicom"></label><div id="selectedFiles" class="selected-files"><span>No files selected</span></div><label class="check"><input type="checkbox" id="resultVerified" required>I confirm the patient identity, source facility and result date have been checked.</label><button class="btn primary" style="width:100%;margin-top:10px">Upload & attach to health record</button></form><div class="section-card"><div class="section-heading"><b>${existing.length}</b><div><h3>Uploaded result register</h3><p>Source documents and review status</p></div></div><div class="uploaded-register">${existing.map((x,i)=>`<div class="uploaded-result"><div class="file-type">${x.name.toLowerCase().endsWith('.pdf')?'PDF':x.name.toLowerCase().endsWith('.dcm')?'DCM':'IMG'}</div><div><strong>${x.type}</strong><span>${x.name}</span><small>${x.date} · ${x.facility} · ${x.size}</small></div>${statusBadge(x.status)}<button class="iconbtn uploaded-action" data-file="${x.name}" title="View result">${icon('file')}</button></div>`).join('')}</div></div></div><div class="upload-security">${icon('alert')}<span><strong>Clinical document control</strong><small>Uploaded files require malware scanning, checksum verification, access logging and clinician review before final status in production.</small></span></div></section>`);$('#resultFiles').onchange=previewResultFiles;$('#resultUploadForm').onsubmit=uploadResultFiles;$$('.uploaded-action').forEach(b=>b.onclick=()=>toast(`${b.dataset.file} opened in secure result viewer`))}
function previewResultFiles(e){let files=[...e.target.files],box=$('#selectedFiles');if(files.some(f=>f.size>25*1024*1024)){toast('Each result file must be 25 MB or smaller');e.target.value='';box.innerHTML='<span>No files selected</span>';return}box.innerHTML=files.length?files.map(f=>`<div>${icon('file')}<span><strong>${f.name}</strong><small>${(f.size/1024/1024).toFixed(2)} MB · Ready to upload</small></span></div>`).join(''):'<span>No files selected</span>'}
function uploadResultFiles(e){e.preventDefault();let files=[...$('#resultFiles').files],category=$('#uploadCategory').value,facility=$('#uploadFacility').value,date=$('#uploadDate').value;if(!files.length)return;files.forEach(f=>state.uploads.unshift({patientId:state.patient.id,name:f.name,type:category,date:new Date(date+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),facility,size:(f.size/1024/1024).toFixed(2)+' MB',status:'Pending review'}));toast(`${files.length} result file${files.length>1?'s':''} uploaded and queued for clinical review`);render()}
function showPassportRegistration(){let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<form class="modal-card registration-modal" id="passportForm"><div class="modal-head"><div><span class="eyebrow" style="color:var(--green2)">Pilgrim portal identity setup</span><h2>Create account from passport</h2><p class="sub">A valid passport and pilgrim photograph are mandatory. Passport biodata becomes the verified identity record.</p></div><button type="button" class="iconbtn" id="closeRegistration">×</button></div><div class="passport-rule">${icon('alert')}<div><strong>Passport-first identification</strong><span>Accounts cannot be created and medical screening cannot be booked without a valid passport number.</span></div></div><div class="registration-grid"><div><div class="section-heading"><b>1</b><div><h3>Passport details</h3><p>Enter details exactly as printed in the passport</p></div></div><div class="form-grid"><label class="field"><span>Passport number *</span><input class="input" id="regPassport" required minlength="6" maxlength="15" pattern="[A-Za-z0-9]+" placeholder="e.g. G3821047"></label><label class="field"><span>Nationality *</span><input class="input" value="Ghanaian" required></label><label class="field"><span>Surname *</span><input class="input" required placeholder="As printed in passport"></label><label class="field"><span>Given names *</span><input class="input" required placeholder="As printed in passport"></label><label class="field"><span>Date of birth *</span><input class="input" type="date" required></label><label class="field"><span>Sex *</span><select class="input" required><option value="">Select</option><option>Female</option><option>Male</option></select></label><label class="field"><span>Date of issue *</span><input class="input" type="date" required></label><label class="field"><span>Date of expiry *</span><input class="input" id="regExpiry" type="date" min="2027-01-01" required></label><label class="field span2"><span>Region of origin or residence *</span><select class="input" required>${ghanaRegions.map(r=>`<option>${r}</option>`).join('')}</select></label></div></div><div><div class="section-heading"><b>2</b><div><h3>Pilgrim photograph</h3><p>Upload a passport-size image or take one now</p></div></div><label class="photo-capture" for="regPhoto"><div id="photoPreview">${icon('users')}</div><strong>Upload or take photograph</strong><span>Use a clear, front-facing image with a plain background.</span><b>Choose camera or photo</b><input type="file" id="regPhoto" accept="image/jpeg,image/png,image/webp" capture="user" required></label><div class="photo-requirements"><b>Image requirements</b><span>• Face fully visible and centred</span><span>• No sunglasses or heavy shadows</span><span>• JPEG, PNG or WebP</span><span>• Maximum 5 MB</span></div><label class="field"><span>Mobile number *</span><input class="input" type="tel" required placeholder="e.g. 024 000 0000"></label><label class="field"><span>Email address</span><input class="input" type="email" placeholder="Optional"></label></div></div><label class="check consent-check"><input type="checkbox" required>I confirm that the passport information belongs to the prospective pilgrim and is accurate.</label><div class="modal-actions"><span>Identity setup creates an auditable pilgrim portal account.</span><button class="btn primary">Verify passport & create account</button></div></form>`;document.body.appendChild(modal);$('#closeRegistration').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};$('#regPhoto').onchange=e=>{let f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Photograph must be 5 MB or smaller');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{$('#photoPreview').innerHTML=`<img src="${reader.result}" alt="Pilgrim photo preview">`};reader.readAsDataURL(f)};$('#passportForm').onsubmit=e=>{e.preventDefault();if(patients.some(p=>p.passport.toUpperCase()===$('#regPassport').value.toUpperCase())){toast('This passport number already has a pilgrim account');return}toast('Passport verified — pilgrim portal account created');setTimeout(()=>modal.remove(),700)}}
function openPassportRegistration(){showPassportRegistration();$('.registration-modal .sub').textContent='Type the passport biodata manually below. No passport scan is required; a valid passport number, agency pathway and pilgrim photograph are mandatory.';$('.passport-rule strong').textContent='Manual passport entry accepted';$('.passport-rule span').textContent='Enter the details exactly as printed in the physical passport. These details create the pilgrim portal identity and enable medical booking.';let regionField=$('.registration-grid .span2');regionField.insertAdjacentHTML('afterend',`<label class="field"><span>Agency pathway *</span><select class="input" id="regAgencyType" required><option value="">Select pathway</option><option value="accredited">Accredited Agent</option><option value="protocol">Protocol / Free Tickets</option><option value="direct">Direct Hajj Pilgrims</option><option value="complementary">Complementary</option><option value="staff">Staff</option></select></label><label class="field hidden" id="accreditedAgentField"><span>Accredited agent *</span><select class="input" id="regAccreditedAgent"><option value="">Select accredited agent</option>${accreditedAgents.map(name=>`<option value="${name}">${name}</option>`).join('')}</select><small>42 accredited-agent names · reference codes pending verification</small></label>`);$('#regAgencyType').onchange=e=>{let accredited=e.target.value==='accredited',field=$('#accreditedAgentField'),select=$('#regAccreditedAgent');field.classList.toggle('hidden',!accredited);select.required=accredited;if(!accredited)select.value=''} }
const statusBadge=s=>`<span class="badge ${s==='Cleared'||s==='Complete'?'green':s.includes('review')||s==='High'?'red':s==='Pending labs'||s==='Partial'||s==='Medium'?'amber':'gray'}"><i class="dot"></i>${s}</span>`;
function dashboard(){let clinician=state.role!=='agent';return `<section class="page"><div class="hero"><div><div class="eyebrow" style="color:var(--green2)">Sunday · 30 August 2026</div><h2>${state.role==='agent'?'Your pilgrim health overview':'Good morning, '+state.user.name.split(' ')[1]+'.'}</h2><p>${state.role==='agent'?'Limited health information for pilgrims assigned to Al-Barakah Travel.':'Here is today’s Hajj medical programme snapshot.'}</p></div><div class="date-chip">Screening phase · Week 04</div></div><div class="stats"><div class="stat"><div class="stat-top"><span>${state.role==='agent'?'ASSIGNED PILGRIMS':'TOTAL REGISTERED'}</span><span class="stat-icon">${icon('users')}</span></div><strong>${state.role==='agent'?'186':'6,482'}</strong><span class="trend">↑ 124 this week</span></div><div class="stat"><div class="stat-top"><span>SCREENED</span><span class="stat-icon">${icon('screen')}</span></div><strong>${state.role==='agent'?'142':'4,819'}</strong><span class="trend">74.3% completed</span></div><div class="stat"><div class="stat-top"><span>VACCINATED</span><span class="stat-icon">${icon('vax')}</span></div><strong>${state.role==='agent'?'109':'3,706'}</strong><span class="trend">Meningitis ACWY tracked</span></div><div class="stat"><div class="stat-top"><span>NEEDS REVIEW</span><span class="stat-icon">${icon('alert')}</span></div><strong>${state.role==='agent'?'8':'217'}</strong><span class="trend" style="color:var(--red)">Clinical follow-up required</span></div></div><div class="grid-main"><div class="card"><div class="card-head"><h3>${state.role==='agent'?'Pilgrims needing attention':'Recent screening activity'}</h3><button class="btn ghost" data-page="pilgrims">View all →</button></div>${patientTable(state.role==='agent'?patients.filter(p=>p.agent.includes('Barakah')):patients.slice(0,4))}</div><div class="stack"><div class="card"><div class="card-head"><h3>Clinic activity</h3><span>Today</span></div><div class="clinic-list">${clinics.slice(0,4).map(c=>`<div class="clinic"><div class="clinic-icon">${icon('clinic')}</div><div class="clinic-main"><strong>${c[0]}</strong><small>${c[1]}</small></div><div class="count"><strong>${c[2]}</strong><small>patients</small></div></div>`).join('')}</div></div>${clinician?`<div class="card"><div class="card-head"><h3>Priority alerts</h3><span>View queue</span></div><div class="alerts"><div class="alert-item"><i class="alert-dot"></i><div><strong>14 abnormal screening results</strong><p>Awaiting physician review</p></div></div><div class="alert-item"><i class="alert-dot" style="background:var(--orange)"></i><div><strong>31 vaccinations overdue</strong><p>Departure within 21 days</p></div></div></div></div>`:''}</div></div></section>`}
function patientTable(list){return `<div class="table-wrap"><table><thead><tr><th>Pilgrim</th><th>Screening</th><th>Risk</th><th>Vaccination</th><th>Last activity</th></tr></thead><tbody>${list.map(p=>`<tr class="clickable" data-patient="${p.id}"><td><div class="person"><div class="avatar">${p.initials}</div><div><strong>${p.name}</strong><small>${p.id} · ${p.age}y · ${p.sex}</small></div></div></td><td>${statusBadge(p.screen)}</td><td>${statusBadge(p.risk)}</td><td>${statusBadge(p.vax)}</td><td>${p.last}</td></tr>`).join('')}</tbody></table></div>`}
function pilgrims(){let list=state.role==='agent'?patients.filter(p=>p.agent.includes('Barakah')):patients;return `<section class="page"><div class="hero"><div><h2>${state.role==='agent'?'My assigned pilgrims':'Pilgrim registry'}</h2><p>${list.length} records shown · Hajj 2027 cohort</p></div><div class="hero-actions"><button class="btn outline" id="allCards">${icon('file')} Generate health cards</button>${state.role==='clinician'||state.role==='admin'?'<button class="btn primary">+ Register pilgrim</button>':''}</div></div><div class="toolbar"><div class="search">${icon('search')}<input class="input" id="patientSearch" placeholder="Search name, ID, phone or agent"></div><select class="input filter" id="riskFilter"><option value="">All risk levels</option><option>High</option><option>Medium</option><option>Low</option></select></div><div class="eligibility-strip"><div>${icon('screen')}<span><strong>${list.filter(certificateEligible).length} certificates automatically generated</strong><small>Screening cleared + mandatory vaccines complete</small></span></div><button class="btn ghost" id="viewEligible">Review certificates →</button></div><div class="card" id="patientResults">${patientTable(list)}</div></section>`}
function record(){let p=state.patient, limited=state.role==='agent'||state.role==='pilgrim';let tabs=state.role==='agent'?[['overview','Overview'],['screeningoutcome','Screening outcome'],['vaccines','Vaccinations'],['history','Clinical history'],['acutecare','Acute care'],['care','Care plan']]:[['overview','Overview'],['screening','Medical screening'],['vaccines','Vaccinations'],['history','Clinical history'],['results','Results & orders'],['care','Care plan'],['privacy','Consent & access']].filter(t=>!limited||!['screening','results'].includes(t[0]));return `<section class="page"><button class="btn ghost" id="back">← Back to pilgrims</button><div class="detail-top"><div class="avatar">${p.initials}</div><div class="detail-name"><h2>${p.name}</h2><div class="meta"><span>Passport: ${p.passport||'Not recorded'}</span><span>Portal ID: ${p.id}</span><span>${p.age} years · ${p.sex}</span><span>${p.region} Region</span><span>${p.agent}</span></div></div>${statusBadge(p.status)}${!limited?'<button class="btn outline" id="ips">Emergency summary</button><button class="btn primary" id="encounter">+ New encounter</button>':'<button class="btn outline" id="ips">My health card</button>'}</div>${p.finding?`<div class="risk-banner">${icon('alert')}<div><strong>Important screening finding</strong><p>${p.finding}. This finding has been carried into the longitudinal clinical record.</p></div></div>`:''}<div class="tabs">${tabs.map(t=>`<button class="tab ${state.tab===t[0]?'active':''}" data-tab="${t[0]}">${t[1]}</button>`).join('')}</div><div id="tabBody">${tabBody(p,limited)}</div></section>`}
function screeningChecklist(p){const history=['History of hypertension','History of diabetes mellitus','History of heart disease / heart failure','History of chronic kidney disease / dialysis','History of chronic liver disease','History of chronic respiratory disease (asthma, COPD)','History of stroke or neurological disorder','Psychiatric illness affecting cognition / advanced dementia','Current pregnancy (state trimester if yes)','Symptoms of active tuberculosis: cough >2 weeks, weight loss or night sweats','Active cancer / current chemotherapy or radiotherapy','Recent fever, haemorrhagic symptoms or travel to a VHF-affected area','Known drug allergies','Current medications (list in remarks)','Previous major surgery'];const vitals=[['Blood pressure','168/96 mmHg','90/60 – 139/89','flag'],['Pulse rate','82 bpm','60 – 100','ok'],['Temperature','36.8 °C','36.1 – 37.5','ok'],['Oxygen saturation','97%','≥ 95%','ok'],['Random blood glucose','9.8 mmol/L','4.0 – 11.1','ok'],['Weight / height / BMI','82 kg / 1.62 m / 31.4','BMI 18.5 – 24.9','flag'],['Mobility assessment','Walks unaided; stairs with rest','Pass / Fail','ok'],['Vision / hearing (60+ years)','Not applicable','Adequate / Impaired','ok']];return `<div class="checklist-form"><div class="section-card"><div class="section-heading"><b>A</b><div><h3>Pilgrim identification</h3><p>Passport-verified identity and screening-centre details</p></div>${statusBadge(p.passport?'Complete':'Missing passport')}</div><div class="form-grid"><label class="field"><span>Full name as in passport</span><input class="input" value="${p.surname}, ${p.given}"></label><label class="field"><span>Region / district</span><input class="input" value="${p.region} Region"></label><label class="field"><span>Date of birth / age</span><input class="input" value="${p.dob||p.age+' years'}"></label><label class="field"><span>Screening centre</span><select class="input"><option>Hajj Village Accra</option><option>Hajj Village Tamale</option></select></label><label class="field"><span>Passport number — primary ID</span><input class="input" value="${p.passport}" required placeholder="Passport required"></label><label class="field"><span>Passport expiry</span><input class="input" type="date" value="${p.expiry}" required></label><label class="field"><span>Next of kin & contact</span><input class="input" value="Sulemana Issah · 024 802 1164"></label><label class="field"><span>Hajj agent / group</span><input class="input" value="${p.agent}"></label></div></div><div class="section-card"><div class="section-heading"><b>B</b><div><h3>Medical history screening</h3><p>Complete through direct pilgrim interview</p></div><span class="progress-text">15 items</span></div><div class="history-list">${history.map((x,i)=>`<div class="history-row"><span class="item-no">${i+1}</span><strong>${x}</strong><label><input type="radio" name="h${i}" ${[0,1,13].includes(i)?'checked':''}> Yes</label><label><input type="radio" name="h${i}" ${![0,1,13].includes(i)?'checked':''}> No</label><input class="mini-input" placeholder="Remarks" value="${i===0?'Diagnosed 2018':i===1?'Metformin 500 mg BD':i===13?'Amlodipine; metformin':''}"></div>`).join('')}</div></div><div class="section-card"><div class="section-heading"><b>C</b><div><h3>Physical examination & vital signs</h3><p>Values outside the reference range are automatically flagged</p></div></div><div class="vital-table"><div class="vital-row vital-head"><span>Parameter</span><span>Result</span><span>Reference</span><span>Flag</span></div>${vitals.map(v=>`<div class="vital-row"><strong>${v[0]}</strong><input class="mini-input" value="${v[1]}"><span>${v[2]}</span><i class="vital-flag ${v[3]}">${v[3]==='ok'?'✓':'!'}</i></div>`).join('')}</div></div><div class="red-flag-callout">${icon('alert')}<div><strong>RED-FLAG ALERT — stop routine screening and refer immediately</strong><p>Active chest pain, syncope, decompensated heart failure, hypertensive emergency, severe uncontrolled respiratory disease, recent major surgery without recovery, active serious/contagious infection, or advanced frailty without an assisted-travel plan. Notify the Central Coordination Unit the same day.</p></div></div><div class="section-card"><div class="section-heading"><b>D</b><div><h3>Screening outcome</h3><p>Age or diagnosis alone does not automatically exclude a pilgrim</p></div></div><div class="outcomes"><label class="outcome green"><input type="radio" name="outcome"><b>GREEN</b><strong>Travel Ready</strong><span>Routine education; cleared for vaccination and travel.</span></label><label class="outcome amber selected"><input type="radio" name="outcome" checked><b>AMBER</b><strong>Travel With Plan</strong><span>Optimisation, assisted-travel plan and re-check required.</span></label><label class="outcome red"><input type="radio" name="outcome"><b>RED</b><strong>Senior Review</strong><span>MDT review; defer only if no safe pathway exists.</span></label></div><div class="form-grid"><label class="field"><span>Condition and required action</span><textarea class="input" rows="2">${p.finding}; physician review and medication optimisation.</textarea></label><label class="field"><span>Referral facility / specialist</span><input class="input" value="Hajj Village Accra · Internal Medicine"></label><label class="field"><span>Target re-check date</span><input class="input" type="date" value="2026-09-03"></label><label class="field"><span>Screening physician</span><input class="input" value="Dr. Efua Mensah"></label></div><div class="form-actions"><span>Positive findings will be highlighted in Clinical History.</span><button class="btn primary" id="saveScreen">Save checklist & synchronise findings</button></div></div></div>`}
function vaccinationChecklist(p,limited){const vaccines=[['Meningococcal ACWY (conjugate)','Mandatory — all pilgrims','18 Aug 2026','MQF-27041 / Jun 2028','IM','complete'],['Yellow fever','Mandatory — all pilgrims','12 Jan 2022','YF-22104 / Dec 2024','SC','complete'],['Poliomyelitis (IPV/bOPV)','Mandatory if applicable','','','IM / Oral','na'],['Seasonal influenza','Recommended','','','IM','due'],['COVID-19','Recommended for selected/high-risk','','','IM','due'],['Tetanus-diphtheria (Td) booster','Recommended if due','','','IM','na'],['Hepatitis B (incomplete series)','Recommended','','','IM','na']];let eligible=certificateEligible(p);let docs=[['International Certificate — Yellow Fever','ICVP-YF-008821','12 Jan 2022',true],['International Certificate — Polio (if applicable)','','',false],['Meningococcal ACWY Certificate','ACWY-27-004821','18 Aug 2026',true],['Hajj Medical Fitness Certificate',eligible?certificateNo(p):'Awaiting eligibility','',eligible]];return `<div class="checklist-form"><div class="section-card"><div class="section-heading"><b>E</b><div><h3>Vaccination checklist</h3><p>Record the date, batch number and expiry for every administered dose</p></div><span class="progress-text">2 complete · 2 due</span></div><div class="vax-table"><div class="vax-row vax-head"><span>Vaccine / requirement</span><span>Previously received</span><span>Dose today</span><span>Batch / expiry</span><span>Site / route</span><span>Status</span></div>${vaccines.map(v=>`<div class="vax-row"><div><strong>${v[0]}</strong><small>${v[1]}</small></div><input class="mini-input" value="${v[2]}" placeholder="Date"><input class="mini-input" placeholder="Date"><input class="mini-input" value="${v[3]}" placeholder="Batch / expiry"><input class="mini-input" value="${v[4]}">${statusBadge(v[5]==='complete'?'Complete':v[5]==='due'?'Due':'N/A')}</div>`).join('')}</div>${!limited?'<button class="btn primary" id="addVax">+ Record vaccination</button>':''}</div><div class="clinical-grid"><div class="section-card"><div class="section-heading"><b>+</b><div><h3>Post-vaccination observation</h3><p>Complete before pilgrim leaves the vaccination area</p></div></div><div class="checklist"><label class="check"><input type="checkbox" checked>30-minute observation completed</label><label class="check"><input type="checkbox">Adverse Event Following Immunisation observed</label><label class="check"><input type="checkbox" checked>Pilgrim counselled on side effects and when to seek care</label></div><div class="recommend">If an AEFI is observed, open and complete an AEFI report before closing this encounter.</div></div><div class="section-card"><div class="section-heading"><b>F</b><div><h3>Documentation & certification</h3><p>Fitness certificate is generated automatically when eligibility rules pass</p></div></div><div class="auto-rule ${eligible?'passed':'waiting'}"><b>${eligible?'✓ Eligibility passed — certificate generated':'○ Certificate pending'}</b><span>${eligible?'Screening cleared and mandatory vaccines complete.':'Requires GREEN screening clearance and all mandatory vaccines.'}</span></div>${docs.map((x,i)=>`<div class="certificate"><input type="checkbox" ${x[3]?'checked':''}><div><strong>${x[0]}</strong><small>${x[1]||'Not issued'}${x[2]?' · '+x[2]:''}</small></div><button class="btn ghost cert-action" data-cert="${i}">${x[3]?'View':'Pending'}</button></div>`).join('')}</div></div><div class="section-card"><div class="section-heading"><b>✓</b><div><h3>Vaccination sign-off</h3><p>Vaccinating nurse and regional quality review</p></div></div><div class="form-grid"><label class="field"><span>Vaccinating nurse</span><input class="input" value="Nurse Fatima Alhassan"></label><label class="field"><span>Vaccination centre</span><input class="input" value="Hajj Village Accra"></label><label class="field"><span>Regional team lead</span><input class="input" placeholder="Name and digital signature"></label><label class="field"><span>Record status</span><select class="input"><option>In progress</option><option>Complete and verified</option></select></label></div><div class="form-actions"><span>Certificate numbers and vaccine batches are included in the audit trail.</span><button class="btn primary" id="saveVaccines">Save vaccination checklist</button></div></div></div>`}
function tabBody(p,limited){if(state.tab==='screeningoutcome')return `<div class="clinical-grid"><div class="panel"><h3>Final screening outcome</h3><div class="auto-rule ${p.status==='Cleared'?'passed':'waiting'}"><b>${p.status==='Cleared'?'GREEN · Travel Ready':'AMBER · Travel With Plan'}</b><span>${p.status==='Cleared'?'Mandatory screening requirements satisfied.':'Medical optimisation and clinical re-check required before final clearance.'}</span></div><div class="kv"><div><small>Screening status</small><strong>${p.status}</strong></div><div><small>Recorded finding</small><strong>${p.finding||'No significant positive finding'}</strong></div><div><small>Required action</small><strong>${p.status==='Cleared'?'Routine travel-health education':'Physician review and medication optimisation'}</strong></div><div><small>Review location</small><strong>Hajj Village Accra · Internal Medicine</strong></div></div></div><div class="panel"><h3>Clearance communication</h3><div class="recommend"><strong>Read-only approved outcome</strong><br>This view shows the final outcome and approved recommendations only. Examination notes and clinician working records remain restricted.</div></div></div>`;
if(state.tab==='acutecare')return `<div class="clinical-grid"><div class="panel"><h3>Acute-care encounters</h3><div class="timeline"><div class="event"><small>06 Jun 2027 · Makkah Clinic</small><strong>Heat exhaustion · Resolved</strong><p>Assessed, orally rehydrated and observed. Discharged stable with hydration and heat-avoidance advice.</p></div><div class="event"><small>Encounter reference</small><strong>AC-${p.id.replace(/\D/g,'').slice(-4)||'4821'}-001</strong><p>No admission, evacuation or continuing emergency treatment recorded.</p></div></div></div><div class="panel"><h3>Current acute-care status</h3><div class="kv"><div><small>Active emergency</small><strong>None</strong></div><div><small>Last disposition</small><strong>Discharged stable</strong></div><div><small>Agent action</small><strong>Encourage hydration and clinic review if symptoms recur</strong></div><div><small>Clinical details</small><strong>Approved summary only</strong></div></div></div></div>`;
if(state.tab==='screening')return screeningChecklist(p);
if(state.tab==='results')return `<div class="clinical-grid"><div class="panel"><div class="panel-title"><h3>Diagnostic results</h3><button class="btn outline" id="newOrder">+ New order</button></div><div class="result-row"><div><strong>HbA1c</strong><small>LOINC 4548-4 · 29 Aug 2026</small></div><b class="critical">8.4% ↑</b></div><div class="result-row"><div><strong>Serum creatinine</strong><small>LOINC 2160-0 · 29 Aug 2026</small></div><b>88 µmol/L</b></div><div class="result-row"><div><strong>Haemoglobin</strong><small>LOINC 718-7 · 29 Aug 2026</small></div><b>12.7 g/dL</b></div></div><div class="panel"><h3>Open orders & referrals</h3><div class="timeline"><div class="event"><small>Priority · due 03 Sep</small><strong>Internal medicine review</strong><p>Reason: uncontrolled hypertension and diabetes.</p></div><div class="event"><small>Routine · before departure</small><strong>ECG, 12 lead</strong><p>Hajj Village Accra diagnostics.</p></div></div></div></div>`;
if(state.tab==='privacy')return `<div class="clinical-grid"><div class="panel"><h3>Consent & information sharing</h3><div class="checklist"><label class="check"><input type="checkbox" checked>Share essential health summary for emergency care during Hajj</label><label class="check"><input type="checkbox" checked>Share approved summary with accredited agent</label><label class="check"><input type="checkbox">Permit de-identified programme research</label></div><button class="btn primary" id="saveConsent">Save consent choices</button></div><div class="panel"><h3>Who accessed this record</h3><div class="timeline"><div class="event"><small>Today · 10:14 GMT</small><strong>Dr. Efua Mensah</strong><p>Viewed clinical summary · Hajj Village Accra</p></div><div class="event"><small>Today · 09:42 GMT</small><strong>Nurse Fatima Alhassan</strong><p>Updated screening observations</p></div><div class="event"><small>18 Aug · 14:03 GMT</small><strong>System</strong><p>Vaccination certificate generated</p></div></div></div></div>`;
if(state.tab==='vaccines')return vaccinationChecklist(p,limited);
if(state.tab==='history')return `<div class="clinical-grid"><div class="panel"><h3>Active conditions & medications</h3>${p.finding?`<div class="risk-banner">${icon('alert')}<div><strong>Screening-derived clinical alert</strong><p>${p.finding}</p></div></div>`:''}<div class="kv"><div><small>Conditions</small><strong>${p.condition}</strong></div><div><small>Drug allergies</small><strong>None known</strong></div><div><small>Regular medicines</small><strong>Amlodipine 10 mg OD<br>Metformin 500 mg BD</strong></div><div><small>ICD-10</small><strong>I10 · E11.9</strong></div></div></div><div class="panel"><h3>Clinical timeline</h3><div class="timeline"><div class="event"><small>30 Aug 2026 · Screening</small><strong>Abnormal blood pressure identified</strong><p>Physician review requested; alert propagated to record.</p></div><div class="event"><small>18 Aug 2026 · Vaccination</small><strong>Meningococcal ACWY administered</strong><p>No immediate adverse event.</p></div><div class="event"><small>12 Aug 2026 · Registration</small><strong>Medical history imported</strong><p>Patient-reported history verified.</p></div></div></div></div>`;
if(state.tab==='care')return `<div class="clinical-grid"><div class="panel"><h3>Health recommendations</h3><div class="recommend"><strong>For the pilgrim and accredited agent</strong><br>Carry prescribed medication in original packaging. Attend physician review before final travel clearance. Maintain hydration and avoid strenuous exertion until blood pressure is controlled.</div></div><div class="panel"><h3>Accommodations & support</h3><div class="kv"><div><small>Mobility support</small><strong>Wheelchair on request</strong></div><div><small>Room allocation</small><strong>Lower floor preferred</strong></div><div><small>Travel companion</small><strong>Not required</strong></div><div><small>Medical follow-up</small><strong>Makkah Clinic</strong></div></div></div></div>`;
return `<div class="clinical-grid"><div class="panel"><h3>Health summary</h3><div class="kv"><div><small>Screening status</small><strong>${p.screen}</strong></div><div><small>Clinical risk</small><strong>${p.risk}</strong></div><div><small>Vaccination</small><strong>${p.vax}</strong></div><div><small>Chronic conditions</small><strong>${p.condition}</strong></div><div><small>Drug allergies</small><strong>None known</strong></div></div></div><div class="panel"><h3>Next actions</h3><div class="timeline"><div class="event"><small>Due 03 Sep 2026</small><strong>Physician review</strong><p>Hajj Village Accra · Medical Room 3</p></div><div class="event"><small>Before departure</small><strong>Influenza vaccination</strong><p>Recommended for travel cohort.</p></div></div></div></div>`}
function generic(type){let map={screening:['Medical screening queue','Mandatory pre-Hajj assessments and clearance decisions.'],vaccinations:['Vaccination programme','Track required immunisations, batches and certificates.'],clinics:['Clinics & acute care','Manage encounters across Ghana and Saudi Arabia.'],reports:['Programme reports','Operational, clinical and compliance reporting.'],settings:['System settings','Access, users and programme configuration.']};let [h,p]=map[type]||map.settings;if(type==='clinics')return `<section class="page"><div class="hero"><div><h2>${h}</h2><p>${p}</p></div><button class="btn primary">+ New encounter</button></div><div class="stats">${clinics.slice(0,4).map(c=>`<div class="stat"><div class="stat-top"><span>${c[1].toUpperCase()}</span><span class="stat-icon">${icon('clinic')}</span></div><strong>${c[2]}</strong><span class="trend">${c[3]} active cases</span></div>`).join('')}</div><div class="card"><div class="card-head"><h3>Clinic network</h3><span>All facilities operational</span></div><div class="clinic-list">${clinics.map(c=>`<div class="clinic"><div class="clinic-icon">${icon('clinic')}</div><div class="clinic-main"><strong>${c[0]}</strong><small>${c[1]} · Open 24 hours during operations</small></div><div class="count"><strong>${c[2]}</strong><small>today</small></div></div>`).join('')}</div></div></section>`;if(type==='vaccinations')return `<section class="page"><div class="hero"><div><h2>${h}</h2><p>${p}</p></div><button class="btn primary">+ Record vaccination</button></div><div class="stats"><div class="stat"><span class="stat-top">FULLY VACCINATED</span><strong>3,706</strong><span class="trend">57.2% cohort</span></div><div class="stat"><span class="stat-top">ACWY ADMINISTERED</span><strong>4,102</strong><span class="trend">Batch tracked</span></div><div class="stat"><span class="stat-top">DUE / OVERDUE</span><strong>614</strong><span class="trend" style="color:var(--red)">Action required</span></div><div class="stat"><span class="stat-top">CERTIFICATES ISSUED</span><strong>3,510</strong><span class="trend">94.7% of complete</span></div></div><div class="card"><div class="card-head"><h3>Recent vaccinations</h3></div>${patientTable(patients)}</div></section>`;return `<section class="page"><div class="hero"><div><h2>${h}</h2><p>${p}</p></div></div><div class="card"><div class="empty">${icon(type==='reports'?'chart':'screen')}<h3>${type==='screening'?'Screening worklist ready':'Module ready for programme configuration'}</h3><p>Select a pilgrim record to continue in this interactive prototype.</p><button class="btn primary" data-page="pilgrims">Open pilgrim registry</button></div></div></section>`}
function safety(){return `<section class="page"><div class="hero"><div><div class="eyebrow" style="color:var(--green2)">Clinical decision support</div><h2>Safety, tasks & escalation</h2><p>Actionable alerts are prioritised; lower-value notifications stay out of the clinician workflow.</p></div><button class="btn primary" id="assignTask">+ Assign task</button></div><div class="stats"><div class="stat"><span class="stat-top">CRITICAL RESULTS</span><strong>3</strong><span class="trend" style="color:var(--red)">Acknowledgement required</span></div><div class="stat"><span class="stat-top">MEDICATION ALERTS</span><strong>8</strong><span class="trend">4 interaction · 4 dose</span></div><div class="stat"><span class="stat-top">OVERDUE TASKS</span><strong>12</strong><span class="trend" style="color:var(--orange)">Escalated to team lead</span></div><div class="stat"><span class="stat-top">CARE GAPS</span><strong>31</strong><span class="trend">Departure within 21 days</span></div></div><div class="clinical-grid"><div class="panel"><h3>Priority clinical alerts</h3><div class="safety-alert red"><b>Critical HbA1c · Amina Sulemana</b><span>8.4% · Review diabetes control before clearance</span><button class="btn outline ack">Acknowledge</button></div><div class="safety-alert amber"><b>Medication interaction · GH27-004744</b><span>Warfarin + clarithromycin · Bleeding risk</span><button class="btn outline ack">Review</button></div><div class="safety-alert amber"><b>Possible duplicate therapy · GH27-004701</b><span>Ibuprofen and diclofenac both active</span><button class="btn outline ack">Review</button></div></div><div class="panel"><h3>Team task board</h3>${[['Physician review','Amina Sulemana','Today · Dr Mensah'],['ECG before clearance','Ibrahim Fuseini','03 Sep · Diagnostics'],['Call pilgrim about vaccine','Mariam Issah','Overdue · Nurse Alhassan']].map((x,i)=>`<div class="task"><input type="checkbox" ${i===1?'checked':''}><div><strong>${x[0]}</strong><small>${x[1]} · ${x[2]}</small></div>${statusBadge(i===2?'High':i===1?'Complete':'Medium')}</div>`).join('')}</div></div></section>`}
function auditSettings(){return `<section class="page"><div class="hero"><div><h2>Governance, access & audit</h2><p>Role permissions, emergency access and immutable record activity.</p></div><button class="btn outline">Export audit log</button></div><div class="clinical-grid"><div class="panel"><h3>Security controls</h3><div class="checklist"><label class="check"><input type="checkbox" checked disabled>Multi-factor authentication required for clinicians</label><label class="check"><input type="checkbox" checked disabled>Encryption in transit and at rest</label><label class="check"><input type="checkbox" checked disabled>Automatic 15-minute session timeout</label><label class="check"><input type="checkbox" checked disabled>Emergency “break-glass” access is audited</label></div><div class="recommend">Agents never receive internal notes, mental-health detail or laboratory values. Emergency access requires a reason and produces a priority audit event.</div></div><div class="panel"><h3>Recent audit events</h3><div class="timeline"><div class="event"><small>10:14 · Record read</small><strong>Dr. Efua Mensah → GH27-004821</strong><p>Purpose: direct care · Accra clinic</p></div><div class="event"><small>09:42 · Observation update</small><strong>Nurse Fatima Alhassan → GH27-004821</strong><p>Blood pressure amended; reason recorded</p></div><div class="event"><small>08:12 · Authentication</small><strong>Abdul Karim · Accredited agent</strong><p>MFA successful · Limited agent scope</p></div></div></div></div></section>`}
function appointmentsPage(){let canProtected=['admin','medicaldirector'].includes(state.role),publicBooking=['pilgrim','agent'].includes(state.role),regionLocked=state.role==='pilgrim';let regionOptions=ghanaRegions.map(r=>`<option ${r==='Northern'?'selected':''}>${r}</option>`).join('');let policy=publicBooking?'':`<div class="capacity-policy"><div><b>Standard daily capacity</b><span>50 per region · 100 for Greater Accra, Ashanti and Northern</span></div>${canProtected?'<div><b>Protected additional pool</b><span>10 per region · visible only to Medical Director and Administrator</span></div>':''}</div>`;let register=state.role==='pilgrim'?'':`<div class="card" style="margin-top:16px"><div class="card-head"><h3>${state.role==='agent'?'Appointments for my pilgrims':'Appointment register'}</h3><span>${state.role==='agent'?'Restricted agency view':'Operational register'}</span></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Pilgrim</th><th>Service</th><th>Region</th><th>Category</th><th>Status</th></tr></thead><tbody>${([['APT-270115-083','Mohammed Abdul-Rahman','Medical screening','Greater Accra','Scheduled']].concat(state.appointments)).map(a=>`<tr><td><strong>${a[0]}</strong></td><td>${a[1]}</td><td>${a[2]}</td><td>${a[3]}</td><td>${a[4]}</td><td>${statusBadge('Confirmed')}</td></tr>`).join('')}</tbody></table></div></div>`;return `<section class="page"><div class="hero"><div><div class="eyebrow" style="color:var(--green2)">Regional appointment booking</div><h2>Screening & vaccination appointments</h2><p>One initial appointment per pilgrim. Clinical follow-ups require an authorised screening decision.</p></div><div class="date-chip">Bookings close 24 hours before each session</div></div>${policy}<div class="booking-layout"><form class="section-card booking-form" id="bookingForm"><div class="section-heading"><b>+</b><div><h3>Book an appointment</h3><p>Valid passport identity and at least 24 hours’ notice are required</p></div></div><label class="field"><span>Service</span><select class="input" id="apptService"><option value="screening">Medical screening</option><option value="vaccination">Vaccination</option></select></label><label class="field"><span>Region of origin or residence</span><select class="input" id="apptRegion" ${regionLocked?'disabled':''}>${regionOptions}</select></label><div class="form-grid"><label class="field"><span>Appointment date</span><input class="input" id="apptDate" type="date" min="2026-09-05" value="2027-01-15" required></label><label class="field"><span>Preferred two-hour session</span><select class="input" id="apptTime"><option>08:00–10:00</option><option>10:00–12:00</option><option>12:00–14:00</option><option>14:00–16:00</option></select></label></div><label class="field"><span>Pilgrim</span>${state.role==='pilgrim'?`<input class="input" value="Amina Sulemana · GH27-004821" readonly>`:`<select class="input" id="apptPilgrim">${patients.map(p=>`<option value="${p.id}">${p.name} · ${p.passport||'NO PASSPORT'}</option>`).join('')}</select>`}</label><div class="passport-status" id="bookingPassport"></div>${canProtected?`<label class="field"><span>Booking pool</span><select class="input" id="apptType"><option value="scheduled">Standard appointment</option><option value="walk-in">Walk-in · protected</option><option value="vip">VIP · protected</option></select></label>`:'<input type="hidden" id="apptType" value="scheduled">'}<div class="slot-check" id="slotCheck"></div><button class="btn primary" id="confirmBooking">Confirm available appointment</button></form><div class="section-card capacity-panel"><div class="section-heading"><b>7</b><div><h3>Available slots this week</h3><p>${regionLocked?'Your registered region':'Select any region above'} · standard slots</p></div></div><div class="region-capacity-list">${['Mon 11 Jan','Tue 12 Jan','Wed 13 Jan','Thu 14 Jan','Fri 15 Jan','Sat 16 Jan','Sun 17 Jan'].map((d,i)=>`<div class="region-cap"><div><strong>${d}</strong><small>08:00 · 10:00 · 12:00 · 14:00</small></div><span>${Math.max(0,22-i*2)} available</span></div>`).join('')}</div>${canProtected?'<div class="readonly-notice"><span><strong>Protected pool</strong><small>Protected availability is shown only in this authorised view.</small></span></div>':''}</div></div>${register}</section>`}
function appointmentPurpose(service){return service==='screening'?'Medical screening':service==='vaccination'?'Vaccination':service==='both'?'Medical screening and vaccination':'Medical review'}
function updateSlotCheck(){let region=$('#apptRegion')?.value,service=$('#apptService')?.value,type=$('#apptType')?.value;if(!region)return;let c=bookingCounts[region],screeningBased=['screening','both','review'].includes(service),special=type!=='scheduled'&&screeningBased,cap=special?10:regionCapacity(region),used=special?c.special:screeningBased?c.screening:c.vaccination,left=Math.max(0,cap-used),el=$('#slotCheck'),restricted=['pilgrim','agent'].includes(state.role);el.className=`slot-check ${left===0?'slot-full':left<=5?'slot-low':'slot-open'}`;el.innerHTML=`<div><strong>${left===0?'No slots remaining':left+' slots available'}</strong><span>${region} · ${appointmentPurpose(service)}${special?' · protected pool':''}</span></div>${restricted?'':`<b>${used} / ${cap}</b>`}`;$('#confirmBooking').disabled=left===0}
function bookingPilgrim(){return state.role==='pilgrim'?patients[0]:patients.find(x=>x.id===$('#apptPilgrim')?.value)}
function updatePassportStatus(){let p=bookingPilgrim(),service=$('#apptService')?.value,el=$('#bookingPassport');if(!p||!el)return;let required=['screening','both','review'].includes(service),valid=!!p.passport&&(!p.expiry||p.expiry>='2027-01-01');el.className=`passport-status ${valid?'verified':'missing'}`;el.innerHTML=valid?`${icon('screen')}<span><strong>Passport verified · ${p.passport}</strong><small>${p.surname}, ${p.given} · Expires ${p.expiry}</small></span>`:`${icon('alert')}<span><strong>${required?'Medical booking blocked':'Passport not recorded'}</strong><small>Add a valid passport number and biodata before medical screening or review can be booked.</small></span>`}
function showBookingSmsReceipt(details){let pilgrimSms=`HajjMed Ghana: ${details.p.name}, appointment confirmed. ${details.purpose} on ${details.date} at ${details.time}, ${details.venue}. Ref: ${details.ref}.`;let agentSms=`HajjMed Ghana: Appointment confirmed for ${details.p.name} (${details.p.passport}). ${details.purpose} on ${details.date} at ${details.time}, ${details.venue}. Ref: ${details.ref}.`;let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card sms-receipt"><div class="modal-head"><div><span class="eyebrow" style="color:var(--green2)">Appointment confirmed</span><h2>SMS notifications queued</h2><p class="sub">Confirmation has been prepared for both the pilgrim and accredited agent.</p></div><button class="iconbtn" id="closeSms">×</button></div><div class="sms-copy"><small>PILGRIM · ${details.p.phone}</small><p>${pilgrimSms}</p></div><div class="sms-copy"><small>ACCREDITED AGENT · ${details.p.agent}</small><p>${agentSms}</p></div><div class="modal-actions"><span>Date, time, venue and appointment purpose included.</span><button class="btn primary" id="doneSms">Done</button></div></div>`;document.body.appendChild(modal);let close=()=>{modal.remove();render()};$('#closeSms').onclick=close;$('#doneSms').onclick=close}
function confirmAppointment(e){e.preventDefault();let region=$('#apptRegion').value,service=$('#apptService').value,type=$('#apptType').value,c=bookingCounts[region],screeningBased=['screening','both','review'].includes(service),special=type!=='scheduled',cap=special?10:regionCapacity(region),used=special?c.special:screeningBased?c.screening:c.vaccination,p=bookingPilgrim(),date=$('#apptDate').value,time=$('#apptTime').value,venue=$('#apptVenue').value,starts=new Date(`${date}T${time.slice(0,5)}:00`);if(appointmentKeys.has(p.passport)){toast('Duplicate blocked — this pilgrim already has an appointment. Amend or cancel the existing booking instead.');return}if(!special&&starts.getTime()-Date.now()<86400000){toast('Booking blocked — standard appointments require at least 24 hours’ notice');return}if(special&&starts.getTime()+7200000<=Date.now()){toast('Protected booking blocked — the selected session has ended');return}if(service==='review'&&!['clinician','admin','medicaldirector'].includes(state.role)){toast('Medical reviews can only be booked from a documented clinical decision');return}if(screeningBased&&(!p.passport||p.expiry<'2027-01-01')){toast('Medical booking blocked — valid passport identity required');return}if(used>=cap){toast('Selected regional session is full — choose another available slot');return}if(special)c.special++;else if(service==='both'){c.screening++;c.vaccination++}else if(screeningBased)c.screening++;else c.vaccination++;appointmentKeys.add(p.passport);let purpose=appointmentPurpose(service),ref=`APT-${date.replaceAll('-','').slice(2)}-${special?(type==='vip'?'V':'W'):''}${String(used+1).padStart(3,'0')}`;state.appointments.unshift([ref,p.name,purpose,region,type==='scheduled'?'Scheduled':type==='vip'?'VIP':'Walk-in',date,time]);showBookingSmsReceipt({ref,p,date,time,venue,purpose})}
function backendConsole(){const modules=[['User & role management','Create accounts, suspend access and assign clinical or administrative permissions.','1,284 users','users'],['Clinical configuration','Manage screening questions, reference ranges, alerts and GREEN/AMBER/RED rules.','Version 2.7','screen'],['Certificate engine','Configure eligibility rules, serial formats, Medical Director signature and revocation.','1 active rule set','file'],['Clinics & locations','Maintain Accra, Tamale, Makkah, Mina and Arafat facilities and service status.','5 active clinics','clinic'],['Interoperability','FHIR endpoints, terminology services, laboratory interfaces and secure data exchange.','FHIR R5 ready','chart'],['Backup & recovery','Encrypted backups, offline synchronization, restoration checks and retention.','Last backup 8 min ago','settings']];return `<section class="page"><div class="hero"><div><div class="eyebrow" style="color:var(--green2)">Restricted executive access</div><h2>Backend administration</h2><p>System configuration, governance and infrastructure controls.</p></div><span class="badge red"><i class="dot"></i>Privileged session</span></div><div class="backend-health"><div><i></i><span><strong>All systems operational</strong><small>API, database, identity and offline sync services healthy</small></span></div><small>Last checked just now</small></div><div class="stats"><div class="stat"><span class="stat-top">ACTIVE USERS</span><strong>1,107</strong><span class="trend">98.4% MFA enrolled</span></div><div class="stat"><span class="stat-top">API AVAILABILITY</span><strong>99.99%</strong><span class="trend">Last 30 days</span></div><div class="stat"><span class="stat-top">PENDING APPROVALS</span><strong>14</strong><span class="trend" style="color:var(--orange)">Requires review</span></div><div class="stat"><span class="stat-top">AUDIT EVENTS TODAY</span><strong>8,421</strong><span class="trend">No critical anomaly</span></div></div><div class="backend-grid">${modules.map(m=>`<button class="backend-module backend-action" data-action="${m[0]}"><span class="stat-icon">${icon(m[3])}</span><div><strong>${m[0]}</strong><p>${m[1]}</p><small>${m[2]}</small></div><b>→</b></button>`).join('')}</div><div class="clinical-grid" style="margin-top:16px"><div class="panel"><div class="panel-title"><h3>Pending privileged actions</h3><button class="btn ghost backend-action" data-action="Approval queue">Review all</button></div>${[['New physician access','Dr. Salifu Mahama · Tamale','Awaiting identity verification'],['Certificate rule publication','Hajj 2027 v2.7','Awaiting Medical Director approval'],['Data export request','Programme evaluation dataset','De-identification check passed']].map(x=>`<div class="approval"><div><strong>${x[0]}</strong><small>${x[1]} · ${x[2]}</small></div><button class="btn outline backend-action" data-action="${x[0]}">Review</button></div>`).join('')}</div><div class="panel"><h3>Infrastructure status</h3>${[['Production API','Operational','32 ms'],['Clinical database','Operational','Encrypted'],['Identity provider','Operational','MFA enforced'],['Offline synchronisation','Operational','24 devices queued']].map(x=>`<div class="infra"><i></i><div><strong>${x[0]}</strong><small>${x[1]}</small></div><span>${x[2]}</span></div>`).join('')}</div></div></section>`}
function showIPS(){let p=state.patient;let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card"><div class="modal-head"><div><span class="eyebrow" style="color:var(--green2)">International Patient Summary</span><h2>Emergency health card</h2></div><button class="iconbtn" id="closeModal">×</button></div><div class="ips-id"><div class="avatar">${p.initials}</div><div><strong>${p.name}</strong><span>${p.id} · ${p.age} years · ${p.sex}</span></div><div class="qr">${qrEligible(p)?`<img src="${qrUrl(p)}" alt="Scannable Hajj health QR code">`:'QR pending'}</div></div>${p.finding?`<div class="risk-banner">${icon('alert')}<div><strong>CLINICAL ALERT</strong><p>${p.finding}</p></div></div>`:''}<div class="ips-grid"><div><small>ALLERGIES / INTOLERANCES</small><strong>No known drug allergies</strong></div><div><small>ACTIVE PROBLEMS</small><strong>${p.condition}</strong></div><div><small>CURRENT MEDICINES</small><strong>${medicineFor(p)}</strong></div><div><small>IMMUNISATIONS</small><strong>MenACWY: ${p.vax} · Yellow fever recorded</strong></div><div><small>FITNESS CERTIFICATE</small><strong>${certificateEligible(p)?certificateNo(p):'Pending requirements'}</strong></div><div><small>EMERGENCY CONTACT</small><strong>Ghana Medical Mission · +966 55 104 2027</strong></div></div><div class="modal-actions"><span>${qrEligible(p)?'QR credential active':'QR generated after screening clearance'} · Updated today</span><button class="btn outline" id="exportIPS">Download / print health card</button></div></div>`;document.body.appendChild(modal);$('#closeModal').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};$('#exportIPS').onclick=()=>downloadable('Pilgrim Health Card '+p.id,healthCardMarkup(p))}
function medicineFor(p){return p.condition.includes('Hypertension')?'Amlodipine 10 mg daily; Metformin 500 mg twice daily':p.condition.includes('Asthma')?'Salbutamol inhaler as required':'No regular medicines documented'}
function healthCardMarkup(p){return `<article class="print-card"><header><div><b>HajjMed Ghana</b><span>HAJJ 2027 PILGRIM HEALTH CARD</span></div><strong>${p.id}</strong></header><section class="identity"><div class="photo">${pilgrimPicture(p)}</div><div><h2>${p.name}</h2><p>${p.age} years · ${p.sex} · ${p.region} Region</p><p>Passport: ${p.passport} · ${p.agent}</p></div><div class="verify">${qrEligible(p)?`<img src="${qrUrl(p)}" alt="Scannable Hajj health QR code">`:'<small>QR after clearance</small>'}</div></section>${p.finding?`<div class="card-alert"><b>MEDICAL ALERT</b><span>${p.finding}</span></div>`:''}<section class="card-grid"><div><small>MEDICAL HISTORY</small><b>${p.condition}</b></div><div><small>ALLERGIES</small><b>No known drug allergies</b></div><div><small>CURRENT MEDICATIONS</small><b>${medicineFor(p)}</b></div><div><small>VACCINATIONS</small><b>MenACWY: ${p.vax==='Complete'?'Complete':'Review record'} · Yellow fever: Recorded</b></div></section><div class="director-sign"><span>Abdul Samed Tanko</span><b>Dr. Abdul Samed Tanko</b><small>Medical Director · Pilgrims Affairs Office Ghana</small></div><footer><span>Scan QR for unified health credential · Emergency: +966 55 104 2027</span><span>Updated 30 Aug 2026</span></footer></article>`}
function downloadable(title,body){let html=`<!doctype html><html><head><meta charset="utf-8"><title>${title}</title><style>body{font:14px Arial;color:#163b35;margin:24px}.print-card,.certificate-print{max-width:760px;margin:0 auto 24px;border:2px solid #0b5e55;border-radius:14px;overflow:hidden;page-break-after:always}.print-card header,.certificate-print header{background:#0b5e55;color:white;padding:14px 18px;display:flex;justify-content:space-between}.print-card header span{display:block;font-size:9px;margin-top:3px}.identity{display:flex;gap:14px;align-items:center;padding:18px}.photo{width:64px;height:78px;border-radius:8px;background:#e7f4ef;display:grid;place-items:center;overflow:hidden;flex:none}.photo img,.photo svg{width:100%;height:100%;object-fit:cover;display:block}.identity div:nth-child(2){flex:1}.identity h2{margin:0 0 5px}.identity p{font-size:11px;margin:3px 0;color:#61756f}.verify{font-size:34px;text-align:center}.verify small{font-size:8px;display:block}.card-alert{margin:0 18px 12px;padding:10px;background:#fff0ee;color:#9b3030;border-left:4px solid #bb3b3b}.card-alert b,.card-alert span{display:block}.card-alert span{font-size:10px;margin-top:3px}.card-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 18px 18px}.card-grid div{background:#f4f7f5;padding:10px;border-radius:7px}.card-grid small,.card-grid b{display:block}.card-grid small{font-size:8px;color:#667a76}.card-grid b{font-size:11px;margin-top:4px}.print-card footer{border-top:1px solid #dbe5e1;padding:10px 18px;display:flex;justify-content:space-between;font-size:9px}.certificate-print{padding-bottom:35px;text-align:center}.certificate-print header{text-align:left}.certificate-print main{padding:38px}.certificate-print h1{font:32px Georgia;margin:10px}.certificate-print .seal{font-size:56px;color:#d5a72c}.certificate-print .cert-name{font:26px Georgia;border-bottom:1px solid #0b5e55;padding:8px}.certificate-print dl{display:grid;grid-template-columns:1fr 1fr;text-align:left;gap:12px;background:#f4f7f5;padding:16px}.certificate-print dt{font-size:9px;color:#667a76}.certificate-print dd{margin:3px 0;font-weight:bold}.director-sign{width:250px;margin:18px 18px 14px auto;text-align:center}.director-sign span{display:block;font:italic 22px 'Segoe Script',cursive;color:#16463f;border-bottom:1px solid #667a76;padding-bottom:2px}.director-sign b,.director-sign small{display:block}.director-sign b{font-size:10px;margin-top:4px}.director-sign small{font-size:8px;color:#667a76;margin-top:2px}@media print{body{margin:0}.print-card,.certificate-print{break-after:page}}</style></head><body>${body}<script>window.onload=()=>window.print()<\/script></body></html>`;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download=title.replace(/\s+/g,'-').toLowerCase()+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function showCertificate(p){if(!certificateEligible(p)){toast('Certificate not generated — screening clearance or mandatory vaccines outstanding');return}let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card certificate-modal"><button class="iconbtn modal-close">×</button><div class="cert-seal">${icon('heart')}</div><span class="eyebrow" style="color:var(--green2)">Pilgrims Affairs Office Ghana</span><h1>Hajj Medical Fitness Certificate</h1><p>This certifies that</p><h2>${p.name}</h2><p>has completed the Hajj 2027 medical screening and mandatory vaccination requirements and is assessed as <b>FIT FOR HAJJ TRAVEL</b>.</p><div class="cert-details"><div><small>Pilgrim ID</small><b>${p.id}</b></div><div><small>Certificate number</small><b>${certificateNo(p)}</b></div><div><small>Issued</small><b>30 August 2026</b></div><div><small>Verification</small><b>Digitally verified ✓</b></div></div><div class="director-sign"><span>Abdul Samed Tanko</span><b>Dr. Abdul Samed Tanko</b><small>Medical Director · Pilgrims Affairs Office Ghana</small></div><div class="modal-actions"><span>Automatically generated from verified screening and vaccination records.</span><button class="btn primary" id="downloadCert">Download / print</button></div></div>`;document.body.appendChild(modal);$('.modal-close',modal).onclick=()=>modal.remove();$('#downloadCert').onclick=()=>downloadable('Medical Fitness Certificate '+p.id,`<article class="certificate-print"><header><b>HajjMed Ghana</b><span>${certificateNo(p)}</span></header><main><div class="seal">✦</div><p>PILGRIMS AFFAIRS OFFICE GHANA</p><h1>Hajj Medical Fitness Certificate</h1><p>This certifies that</p><div class="cert-name">${p.name}</div><p>has completed the Hajj 2027 medical screening and mandatory vaccination requirements and is assessed as <b>FIT FOR HAJJ TRAVEL</b>.</p><dl><div><dt>PILGRIM ID</dt><dd>${p.id}</dd></div><div><dt>CERTIFICATE NUMBER</dt><dd>${certificateNo(p)}</dd></div><div><dt>ISSUED</dt><dd>30 August 2026</dd></div><div><dt>STATUS</dt><dd>Digitally verified</dd></div></dl><div class="director-sign"><span>Abdul Samed Tanko</span><b>Dr. Abdul Samed Tanko</b><small>Medical Director · Pilgrims Affairs Office Ghana</small></div></main></article>`)}
const rawDownloadable=downloadable;
downloadable=function(title,body){return rawDownloadable(title,`<style>.verify{width:82px;height:82px}.verify img{width:82px;height:82px;display:block}.certificate-qr{text-align:center;margin:16px auto}.certificate-qr img{display:block;margin:auto}.certificate-qr span{display:block;font-size:8px;color:#667a76;margin-top:4px}</style>${body}`)}
const baseShowCertificate=showCertificate;
showCertificate=function(p){baseShowCertificate(p);if(!certificateEligible(p))return;let qr=`<div class="certificate-qr"><img src="${qrUrl(p)}" alt="Scannable Hajj health QR code"><span>Scan unified health credential</span></div>`;$('.certificate-modal .cert-details').insertAdjacentHTML('afterend',qr);$('#downloadCert').onclick=()=>downloadable('Medical Fitness Certificate '+p.id,certificatePrintableMarkup(p))}
function certificatePrintableMarkup(p){return `<article class="certificate-print"><header><b>HajjMed Ghana</b><span>${certificateNo(p)}</span></header><main><div class="seal">✦</div><p>PILGRIMS AFFAIRS OFFICE GHANA</p><h1>Hajj Medical Fitness Certificate</h1><p>This certifies that</p><div class="cert-name">${p.name}</div><p>has completed the Hajj 2027 medical screening and mandatory vaccination requirements and is assessed as <b>FIT FOR HAJJ TRAVEL</b>.</p><dl><div><dt>PASSPORT</dt><dd>${p.passport}</dd></div><div><dt>CERTIFICATE NUMBER</dt><dd>${certificateNo(p)}</dd></div><div><dt>ISSUED</dt><dd>30 August 2026</dd></div><div><dt>STATUS</dt><dd>Digitally verified</dd></div></dl><div class="certificate-qr"><img style="width:110px;height:110px" src="${qrUrl(p)}" alt="Scannable Hajj health QR code"><span>Scan for medical, fitness and vaccination credential</span></div><div class="director-sign"><span>Abdul Samed Tanko</span><b>Dr. Abdul Samed Tanko</b><small>Medical Director · Pilgrims Affairs Office Ghana</small></div></main></article>`}
function showCredentialQR(p){if(!qrEligible(p)){toast('QR credential is generated after medical clearance');return}let modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card qr-credential"><button class="iconbtn modal-close">×</button><div class="qr-code-large"><img src="${qrUrl(p)}" alt="Scannable Hajj health QR code"></div><div><span class="eyebrow" style="color:var(--green2)">Unified Hajj health credential</span><h2>${p.name}</h2><p>${p.passport} · ${p.id}</p><div class="ips-grid"><div><small>MEDICAL HISTORY</small><strong>${p.condition}</strong></div><div><small>ALLERGIES</small><strong>No known drug allergies</strong></div><div><small>CURRENT MEDICINES</small><strong>${medicineFor(p)}</strong></div><div><small>VACCINATION CARD</small><strong>MenACWY ${p.vax} · Yellow fever recorded</strong></div><div><small>FITNESS CERTIFICATE</small><strong>${certificateEligible(p)?certificateNo(p):'Pending mandatory vaccination'}</strong></div><div><small>QR STATUS</small><strong>Active · Screening cleared</strong></div></div><p class="qr-note">Scanning this code displays the approved health-card, fitness and vaccination summary.</p></div></div>`;document.body.appendChild(modal);$('.modal-close',modal).onclick=()=>modal.remove()}
function injectVaccinationQR(){if(state.tab!=='vaccines'||!state.patient)return;let cards=$$('.section-card'),docs=cards.find(c=>c.textContent.includes('Documentation & certification'));if(!docs||docs.querySelector('.qr-vax-row'))return;let active=qrEligible(state.patient);docs.insertAdjacentHTML('beforeend',`<div class="certificate qr-vax-row"><div class="mini-qr">${active?`<img src="${qrUrl(state.patient)}" alt="Health credential QR code">`:'○'}</div><div><strong>Unified Hajj health QR credential</strong><small>${active?'Active · Medical screening cleared':'Generated automatically after clearance'}</small></div><button class="btn ghost" id="viewHealthQR">${active?'View QR':'Pending'}</button></div>`);$('#viewHealthQR').onclick=()=>showCredentialQR(state.patient)}
function generateAllCards(){downloadable('Hajj 2027 Pilgrim Health Cards',patients.map(healthCardMarkup).join(''));toast(`${patients.length} pilgrim health cards generated`)}
function pilgrimPicture(p){return p.photo?`<img src="${p.photo}" alt="${p.name} profile photograph">`:`<svg viewBox="0 0 120 140" role="img" aria-label="Pilgrim profile photograph"><rect width="120" height="140" rx="12" fill="#dcece6"/><circle cx="60" cy="52" r="25" fill="#a96e4f"/><path d="M30 128c2-30 12-48 30-48s28 18 30 48" fill="#0b5e55"/><path d="M28 75c1-36 13-57 32-57s31 21 32 57L79 91c-5-8-11-12-19-12s-14 4-19 12z" fill="#d5a72c"/><circle cx="51" cy="51" r="2" fill="#30241f"/><circle cx="69" cy="51" r="2" fill="#30241f"/><path d="M53 65q7 5 14 0" fill="none" stroke="#6f3f32" stroke-width="2" stroke-linecap="round"/></svg>`}
function myhealth(){state.patient=patients[0];let p=state.patient;return `<section class="page"><div class="pilgrim-hero"><div><div class="eyebrow" style="color:var(--green2)">Pilgrim portal · Hajj 2027</div><h2>As-salamu alaykum, Amina.</h2><p>Your medical clearance, vaccination and travel health information.</p><div class="passport-chip">${icon('screen')} Passport verified · ${p.passport}</div></div><div class="dashboard-photo">${pilgrimPicture(p)}<span>Profile photograph</span></div></div>${record().replace('<section class="page"><button class="btn ghost" id="back">← Back to pilgrims</button>','<section>')}</section>`}
function render(){if(!state.user)return login();$('#app').innerHTML=shell();let html=state.page==='dashboard'?dashboard():state.page==='appointments'?appointmentsPage():state.page==='pilgrims'?pilgrims():state.page==='record'?record():state.page==='myhealth'?myhealth():state.page==='communications'?communicationsPage():state.page==='safety'?safety():state.page==='settings'?auditSettings():state.page==='backend'?backendConsole():generic(state.page);$('#content').innerHTML=html;wire();$$('[data-patient]').forEach(r=>r.onclick=()=>{state.patient=patients.find(p=>p.id===r.dataset.patient);state.page='record';state.tab='overview';render()});$$('[data-tab]').forEach(t=>t.onclick=()=>{state.tab=t.dataset.tab;render()});const booking=$('#bookingForm');if(booking){booking.onsubmit=confirmAppointment;['apptRegion','apptType','apptDate'].forEach(id=>{let e=$('#'+id);if(e)e.onchange=updateSlotCheck});const service=$('#apptService');service.onchange=()=>{updateSlotCheck();updatePassportStatus()};const pilgrim=$('#apptPilgrim');if(pilgrim)pilgrim.onchange=updatePassportStatus;updateSlotCheck();updatePassportStatus()}const back=$('#back');if(back)back.onclick=()=>{state.page=state.role==='pilgrim'?'myhealth':'pilgrims';render()};const ips=$('#ips');if(ips)ips.onclick=showIPS;const allCards=$('#allCards');if(allCards)allCards.onclick=generateAllCards;const viewEligible=$('#viewEligible');if(viewEligible)viewEligible.onclick=()=>showCertificate(patients.find(certificateEligible));$$('.cert-action').forEach(b=>b.onclick=()=>b.dataset.cert==='3'?showCertificate(state.patient):toast('Vaccination certificate opened'));$$('.backend-action').forEach(b=>b.onclick=()=>toast(`${b.dataset.action} opened in secure backend console`));const search=$('#patientSearch'),filter=$('#riskFilter');if(search){const go=()=>{let q=search.value.toLowerCase(),risk=filter.value;let list=(state.role==='agent'?patients.filter(p=>p.agent.includes('Barakah')):patients).filter(p=>(p.name+p.id+p.phone+p.agent).toLowerCase().includes(q)&&(!risk||p.risk===risk));$('#patientResults').innerHTML=patientTable(list);$$('[data-patient]').forEach(r=>r.onclick=()=>{state.patient=patients.find(p=>p.id===r.dataset.patient);state.page='record';render()})};search.oninput=go;filter.onchange=go}['saveScreen','saveVaccines','addVax','encounter','saveConsent','newOrder','assignTask'].forEach(id=>{let e=$('#'+id);if(e)e.onclick=()=>toast(id==='saveScreen'?'Screening checklist saved — eligibility re-evaluated and findings synchronised':id==='saveVaccines'?'Vaccination saved — certificate eligibility re-evaluated':id==='saveConsent'?'Consent choices saved with audit event':id==='newOrder'?'Diagnostic order composer opened':id==='assignTask'?'Task assignment opened':id==='addVax'?'Vaccination record added':'New clinical encounter opened')});$$('.ack').forEach(e=>e.onclick=()=>{e.closest('.safety-alert').classList.add('resolved');e.textContent='Acknowledged';toast('Alert acknowledged and audit event recorded')});}
function toast(msg){let t=document.createElement('div');t.className='toast';t.textContent='✓ '+msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2800)}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
login();
